import SwiftUI
import Foundation

// Dados do Plano de leitura (cronograma por disciplina) e do Índice Estrutural das Normas.
// Extraídos dos HTMLs originais da Lana; embutidos como JSON e decodificados em runtime
// (o build usa swiftc puro, sem bundle de recursos).

struct PlanTitRef: Codable, Hashable { let num: String; let name: String }
struct PlanDay: Codable, Hashable { let d: String; let a: String; let t: [PlanTitRef]? }
struct PlanLaw: Codable, Hashable { let name: String; let color: String; let days: [PlanDay] }
struct PlanDiscipline: Codable, Hashable { let name: String; let color: String; let laws: [PlanLaw] }

struct IdxCap: Codable, Hashable { let k: String; let d: String }
struct IdxTitulo: Codable, Hashable { let num: String; let name: String; let arts: String; let caps: [IdxCap] }
struct IdxCode: Codable, Hashable {
    let id: String; let color: String; let abbr: String; let name: String
    let ct: String; let full: String; let meta: [String]; let titulos: [IdxTitulo]
}

